#pragma once
#include <stdint.h>

// Large clock digits generated by tools/gen_fonts.py. Glyph order: "0123456789:-".
// Each pixel byte: high nibble = glyph coverage, low nibble = outline coverage.
typedef struct {
    uint8_t adv;        // advance width (without padding)
    uint8_t w, h;       // bitmap size including `pad` on every side
    const uint8_t *px;
} font_glyph_t;

typedef struct {
    uint8_t h, pad;
    font_glyph_t glyphs[12];
} font_t;

extern const font_t font_round_xxl, font_round_xl, font_round_m, font_round_s;  // xxl: 176 px, for full-screen faces
extern const font_t font_seg_xxl, font_seg_xl, font_seg_m, font_seg_s;
extern const font_t font_nib_m, font_nib_s;  // calligraphic serif digits (JRPG menus)
